// Select max 5 NEW leads ('Pending'/empty) + due Follow-Ups matching Prospects Stage column
const MAX_NEW_DAILY = 5;
const MAX_FOLLOWUP_DAILY = 5;

const rows = $input.all();
if (!rows || rows.length === 0) return [];

const todayStr = new Date().toISOString().split('T')[0];
const nowMs = Date.now();
const newLeads = [];
const followUps = [];

function normalizePhone(raw) {
  let p = (raw || '').toString().replace(/[^0-9+]/g, '');
  if (!p) return '';
  if (!p.startsWith('+')) {
    if (p.length === 10) p = '+91' + p;
    else if (p.length === 12 && p.startsWith('91')) p = '+' + p;
    else p = '+' + p;
  }
  return p.length >= 11 ? p : '';
}

function addDays(days) {
  const d = new Date(nowMs + days * 24 * 60 * 60 * 1000);
  return d.toISOString().split('T')[0];
}

for (const item of rows) {
  const r = item.json;
  const phone = normalizePhone(r['Phone'] || r['WhatsApp'] || r['Mobile'] || r['phone']);
  if (!phone) continue;

  const stage = (r['Stage'] || '').toString().trim();
  const stageLower = stage.toLowerCase();

  // Skip terminal / paused stages
  if (['follow up 3', 'call booked', 'rejected', 'maybe later'].includes(stageLower)) continue;

  const businessName = (r['Business'] || r['Business Name'] || r['Company'] || r['Name'] || 'Team').toString().trim();
  const ownerName = (r['Owner Name'] || r['Contact Name'] || businessName).toString().trim();
  const address = (r['Address'] || '').toString().trim();
  const city = (r['City'] || r['Location'] || (address ? address.split(',').slice(-2, -1)[0]?.trim() : '') || 'your area').toString().trim();
  const rating = r['Rating'] || '';
  const reviews = r['Reviews'] || '';
  const website = (r['Website'] || '').toString().trim();
  const need = (r['Need'] || '').toString().trim();

  // 1. Pick up to 5 NEW leads (Stage is Pending or empty)
  if ((stageLower === '' || stageLower === 'pending') && newLeads.length < MAX_NEW_DAILY) {
    newLeads.push({
      json: {
        actionType: 'OUTREACH',
        nextStage: 'Cold outreach',
        contactedDate: todayStr,
        nextFollowUpDate: addDays(3),
        phone,
        businessName,
        ownerName,
        city,
        rating,
        reviews,
        website,
        need
      }
    });
    continue;
  }

  // 2. Check due Follow-Ups (Cold outreach -> Follow up 1 -> Follow up 2 -> Follow up 3)
  if (['cold outreach', 'follow up 1', 'follow up 2'].includes(stageLower) && followUps.length < MAX_FOLLOWUP_DAILY) {
    const nextDue = (r['Next follow-up'] || '').toString().trim();
    const contacted = (r['Contacted Date'] || '').toString().trim();

    let isDue = false;
    if (nextDue) {
      isDue = nextDue <= todayStr;
    } else if (contacted) {
      const daysSince = (nowMs - Date.parse(contacted)) / (1000 * 60 * 60 * 24);
      isDue = !isNaN(daysSince) && daysSince >= 3;
    }

    if (isDue) {
      let actionType = 'FOLLOWUP_1';
      let nextStage = 'Follow up 1';
      let nextFollowUpDate = addDays(4);

      if (stageLower === 'follow up 1') {
        actionType = 'FOLLOWUP_2';
        nextStage = 'Follow up 2';
        nextFollowUpDate = addDays(7);
      } else if (stageLower === 'follow up 2') {
        actionType = 'FOLLOWUP_3';
        nextStage = 'Follow up 3';
        nextFollowUpDate = '';
      }

      followUps.push({
        json: {
          actionType,
          nextStage,
          contactedDate: contacted || todayStr,
          nextFollowUpDate,
          phone,
          businessName,
          ownerName,
          city,
          rating,
          reviews,
          website,
          need
        }
      });
    }
  }
}

return [...newLeads, ...followUps];

const lead = $json;
const name = lead.ownerName || lead.businessName;
const biz = lead.businessName;
const location = lead.city || 'your area';
const website = (lead.website || '').trim();
const isSocial = /(facebook\.com|instagram\.com|indiamart\.com|justdial\.com|linkedin\.com)/i.test(website);
const hasWebsite = Boolean(website && website.length > 7 && !isSocial);

const revNum = parseInt(lead.reviews, 10);
const revText = !isNaN(revNum) && revNum > 0 ? ` and *${revNum} ${revNum === 1 ? 'review' : 'reviews'}*` : '';
const ratingStr = lead.rating ? ` (great to see your *${lead.rating}★* rating${revText}!)` : '';

let whatsappMessage = '';

if (lead.actionType === 'OUTREACH') {
